from normalize_path import normalize_path
import pytest

CASES = [
    ('', '.'),
    ('.', '.'),
    ('..', '..'),
    ('/', '/'),
    ('//', '/'),
    ('///', '/'),
    ('/..', '/'),
    ('/../..', '/'),
    ('//foo', '/foo'),
    ('//foo//bar', '/foo/bar'),
    ('///foo', '/foo'),
    ('foo', 'foo'),
    ('foo/bar', 'foo/bar'),
    ('foo//bar', 'foo/bar'),
    ('foo/./bar', 'foo/bar'),
    ('foo/bar/', 'foo/bar'),
    ('foo/bar/.', 'foo/bar'),
    ('foo/bar/..', 'foo'),
    ('foo/..', '.'),
    ('/foo/..', '/'),
    ('foo/../bar', 'bar'),
    ('foo/bar/../baz', 'foo/baz'),
    ('foo/../../bar', '../bar'),
    ('foo/bar/../../..', '..'),
    ('foo/bar/../../../baz', '../baz'),
    ('../foo', '../foo'),
    ('../../foo', '../../foo'),
    ('/foo/bar/../../baz', '/baz'),
    ('/foo/bar/../../../baz', '/baz'),
    ('./foo', 'foo'),
    ('foo/././bar', 'foo/bar'),
    ('...', '...'),
    ('.hidden', '.hidden'),
    ('foo/.hidden/..', 'foo'),
    ('foo/bar/../.hidden', 'foo/.hidden'),
    ('a b/c d', 'a b/c d'),
    ('a\\b', 'a\\b'),
    ('a\\/b', 'a\\/b'),
    ('/foo bar/../baz', '/baz'),
    ('foo/\n/bar', 'foo/\n/bar'),
    ('..foo', '..foo'),
    ('foo..', 'foo..'),
    ('foo/.../bar', 'foo/.../bar'),
    ('/././.', '/'),
    ('././.', '.'),
    ('a/b/c/../../d', 'a/d'),
    ('/a/./b/../../c', '/c'),
    ('../..', '../..'),
    ('/../a/../b', '/b'),
    ('a//../b//', 'b'),
    ('//..//foo', '/foo'),
    ('foo/bar/baz/../../..', '.'),
    ('/foo/bar/baz/../../..', '/'),
    ('ü/ö/../ü', 'ü/ü'),
    ('', ''),
    ('', ''),
]

def test_cases():
    for raw, expected in CASES:
        assert normalize_path(raw) == expected

def test_rejects_nul():
    with pytest.raises(ValueError):
        normalize_path('a\x00b')

def test_rejects_too_long():
    with pytest.raises(ValueError):
        normalize_path('a' * 4097)

def test_accepts_max_length():
    raw = 'a' * 4096
    assert normalize_path(raw) == raw
